for _ in range(int(input())):
	(n, m) = map(int, input().split())
	(a, b) = map(int, input().split())
	a -= 1
	b -= 1
	(c, d) = map(int, input().split())
	c -= 1
	d -= 1
	mat = [[4] * m for i in range(n)]
	mat[a][b] = 1
	mat[c][d] = 2
	for i in range(n):
		for j in range(m):
			if i == a and j == b or (i == c and j == d):
				continue
			elif (i + j) % 2 == (a + b) % 2:
				mat[i][j] = 1
			elif (i + j) % 2 == (c + d) % 2:
				mat[i][j] = 2
	for i in mat:
		print(*i)
